package com.madar.files;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.zip.*;
/** Isolated, local-only editor surface. Native code owns credentials, files and cloud jobs. */
public final class MotionStudioActivity extends Activity {
 private WebView web;private LocalMediaServer server;private File assets;private volatile String id;private String pending="",pendingScene="";private boolean busy,loaded,destroyed;private JSONArray candidates=new JSONArray();private String candidateScene="";
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final AtomicBoolean cancel=new AtomicBoolean();
 private final android.content.BroadcastReceiver events=new android.content.BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String raw=i.getStringExtra("event");if(raw!=null)try{JSONObject e=new JSONObject(raw);if(id.equals(e.optString("project")))send(e);}catch(Exception ignored){}}};
 @Override public void onCreate(Bundle state){super.onCreate(state);try{
  String selected=state==null?getIntent().getStringExtra("project"):state.getString("project");if(selected==null)selected=getSharedPreferences("motion-studio",0).getString("last",null);JSONObject p;try{p=MotionProject.load(this,selected);}catch(Exception e){p=MotionProject.create(this);}id=p.getString("id");if(state!=null){pending=state.getString("pending","");pendingScene=state.getString("scene","");}
  assets=new File(getCacheDir(),"motion-web");if(!assets.isDirectory()&&!assets.mkdirs())throw new IOException();for(String name:new String[]{"index.html","style.css","app.js","core.js","product.js","creative.js","Cairo.ttf"})try(InputStream in=getAssets().open("motion/"+name);OutputStream out=new FileOutputStream(new File(assets,name))){FilesUtil.copy(in,out);}
  server=new LocalMediaServer((route,name)->{if(Arrays.asList("index.html","style.css","app.js","core.js","product.js","creative.js","Cairo.ttf").contains(route))return new LocalMediaServer.Media(new File(assets,route),route.endsWith(".html")?"text/html":route.endsWith(".css")?"text/css":route.endsWith(".ttf")?"font/ttf":"application/javascript");if(route.equals("asset"))return new LocalMediaServer.Media(MotionProject.asset(this,id,name),name.endsWith(".wav")?"audio/wav":"image/jpeg");if(route.equals("project"))return new LocalMediaServer.Media(MotionProject.asset(this,id,"project.json"),"application/json");if(route.equals("result"))return new LocalMediaServer.Media(FilesUtil.resolve(this,name),"video/mp4");return null;});
  web=new WebView(this);web.setBackgroundColor(Color.rgb(242,236,224));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setDomStorageEnabled(false);settings.setMediaPlaybackRequiresUserGesture(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"MotionNative");
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(server.owns(r.getUrl()))return null;return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsConfirm(WebView v,String u,String message,JsResult result){new AlertDialog.Builder(MotionStudioActivity.this).setTitle("استوديو الفيديو").setMessage(message).setPositiveButton("تأكيد",(d,w)->result.confirm()).setNegativeButton("رجوع",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});
  android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.addView(web);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);web.loadUrl(server.base()+"/index.html");androidx.core.content.ContextCompat.registerReceiver(this,events,new IntentFilter(MotionStudioService.EVENT),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);
 }catch(Exception e){new AlertDialog.Builder(this).setMessage("تعذر فتح استوديو الفيديو").setPositiveButton("رجوع",(d,w)->finish()).show();}}
 private final class Bridge{@JavascriptInterface public void request(String raw){if(raw==null||raw.length()>800000)return;runOnUiThread(()->{try{handle(new JSONObject(raw));}catch(Exception e){error(e.getMessage()==null?"تعذر تنفيذ الطلب":e.getMessage());}});}}
 private void send(JSONObject e){runOnUiThread(()->{if(!destroyed&&web!=null)web.evaluateJavascript("window.receive("+e.toString()+")",null);});}
 private void error(String message){try{send(new JSONObject().put("type","error").put("message",message));}catch(Exception ignored){}}
 private boolean active(){return MotionStudioService.active&&id.equals(MotionStudioService.projectId);}
 private void editable()throws IOException{if(busy||active())throw new IOException("انتظر اكتمال المهمة أو ألغها أولًا");}
 private void load()throws Exception{JSONObject p=MotionProject.load(this,id);JSONObject state=GeminiCheckpoint.read(MotionProject.asset(this,id,"state.json"));if(state!=null&&state.optString("status").equals("running")&&!active())state.put("status","interrupted").put("message","توقفت المهمة قبل اكتمالها؛ المشروع محفوظ ويمكن إعادة المحاولة");send(new JSONObject().put("type","project").put("project",p).put("projects",MotionProject.list(this)).put("draft",MotionProject.draft(this,id)).put("state",state==null?new JSONObject():state).put("seed",getIntent().getStringExtra("prompt")).put("warning",getSharedPreferences("motion-studio",0).getString("cleanupWarning","")));}
 private JSONObject scene(JSONObject p,String scene)throws Exception{JSONArray ss=p.getJSONArray("scenes");for(int i=0;i<ss.length();i++)if(ss.getJSONObject(i).getString("id").equals(scene))return ss.getJSONObject(i);throw new IOException("المشهد تغيّر؛ اختره من جديد");}
 private void task(String label,Work work)throws Exception{editable();busy=true;cancel.set(false);send(new JSONObject().put("type","busy").put("message",label));worker.execute(()->{try{work.run();}catch(Exception e){error(e instanceof IOException?e.getMessage():"تعذر إكمال الطلب؛ مشروعك محفوظ");}finally{busy=false;try{load();}catch(Exception e){error("تعذر تحميل المشروع");}}});}
 interface Work{void run()throws Exception;}
 private void handle(JSONObject r)throws Exception{String action=r.getString("action");switch(action){
  case "ready":loaded=true;load();break;
  case "load":load();break;
  case "save":editable();JSONObject saved=r.getJSONObject("project");if(!id.equals(saved.getString("id")))throw new IOException("المشروع غير مطابق");MotionProject.save(this,saved);break;
  case "saveDraft":if(!id.equals(r.getString("id")))throw new IOException("المشروع تغيّر");MotionProject.saveDraft(this,id,r.getJSONObject("draft"));send(new JSONObject().put("type","draftSaved"));break;
  case "new":editable();id=MotionProject.create(this).getString("id");getIntent().removeExtra("prompt");load();break;
  case "open":editable();id=MotionProject.load(this,r.getString("id")).getString("id");getIntent().removeExtra("prompt");load();break;
  case "settings":TranslationSettings.show(this);break;
  case "plan":if(!r.optBoolean("consent"))throw new IOException("فعّل الموافقة على المعالجة السحابية");String prompt=r.getString("prompt");task("تجهيز المشاهد من النص",()->{JSONObject p=MotionPlanner.plan(this,MotionProject.load(this,id),prompt,cancel);MotionProject.save(this,p);});break;
  case "autoImages":if(!r.optBoolean("consent"))throw new IOException("فعّل الموافقة السحابية أولًا");task("اقتراح صور للمشاهد",()->{JSONObject p=MotionProject.load(this,id);JSONArray scenes=p.getJSONArray("scenes");for(int i=0;i<scenes.length();i++){ColabProbe.check(cancel);JSONObject sc=scenes.getJSONObject(i);if(!sc.optString("image").isEmpty()||sc.optString("imageQuery").trim().isEmpty())continue;send(new JSONObject().put("type","busy").put("message","اقتراح صورة للمشهد "+(i+1)+" / "+scenes.length()));JSONArray found=MotionImages.search(sc.getString("imageQuery"),cancel);int chosen=MotionPlanner.chooseImage(this,sc,found,cancel);if(chosen<0)continue;JSONObject chosenImage=found.getJSONObject(chosen);sc.put("image",MotionImages.download(this,id,chosenImage,cancel)).put("credit",chosenImage.getString("credit")).put("illustration",false).put("imageManual",false).put("imageAt",sc.optDouble("start",0));if(p.optBoolean("ready")&&!sc.optString("imageAnchor").isEmpty())sc.put("imageAt",JSONObject.NULL).put("needsReview",true);p.remove("result");MotionProject.save(this,p);}send(new JSONObject().put("type","notice").put("message","اكتملت اقتراحات الصور المتاحة؛ راجع مطابقتها للقصة قبل التصدير"));});break;
  case "search":String query=r.getString("query"),sid=r.getString("scene");task("البحث عن صور للمشهد",()->{scene(MotionProject.load(this,id),sid);candidates=MotionImages.search(query,cancel);candidateScene=sid;JSONArray display=new JSONArray();for(int i=0;i<candidates.length();i++){JSONObject v=candidates.getJSONObject(i);display.put(new JSONObject().put("index",i).put("title",v.getString("title")).put("credit",v.getString("credit")));}send(new JSONObject().put("type","candidates").put("scene",sid).put("items",display));});break;
  case "chooseImage":int index=r.getInt("index");String target=r.getString("scene");if(!candidateScene.equals(target)||index<0||index>=candidates.length())throw new IOException("نتيجة بحث غير صالحة");JSONObject image=candidates.getJSONObject(index);task("تنزيل صورة المشهد",()->{JSONObject p=MotionProject.load(this,id),s=scene(p,target);s.put("image",MotionImages.download(this,id,image,cancel)).put("credit",image.getString("credit")).put("illustration",false).put("imageManual",false);if(!p.optBoolean("ready"))s.put("imageAt",s.optDouble("start",0));else if(!s.optString("imageAnchor").isEmpty()){s.put("imageAt",JSONObject.NULL).put("needsReview",true);}p.remove("result");MotionProject.save(this,p);});break;
  case "generateImage":if(!r.optBoolean("consent"))throw new IOException("فعّل الموافقة على المعالجة السحابية");String imageScene=r.getString("scene");task("قوقل يولّد تصويرًا توضيحيًا للمشهد",()->{JSONObject p=MotionProject.load(this,id),s=scene(p,imageScene);String q=r.optString("prompt",s.getString("imageQuery"));if(q.trim().isEmpty())throw new IOException("اكتب وصف الصورة والحقبة المطلوبة");File generated=GeminiImages.generate(this,"Create a restrained historically contextual illustrative image: "+q+". Do not add text or logos. This is an artistic reconstruction, not a historical photograph or documentary evidence. Warm muted colors.",null,cancel);try{s.put("image",MotionImages.store(this,id,generated)).put("illustration",true).put("imageManual",false).put("credit","تصوير توضيحي مولّد بواسطة قوقل").put("imageAt",s.optDouble("start",0));if(p.optBoolean("ready")&&!s.optString("imageAnchor").isEmpty())s.put("imageAt",JSONObject.NULL).put("needsReview",true);p.remove("result");MotionProject.save(this,p);}finally{generated.delete();}});break;
  case "pickProductImage":editable();if(!MotionProject.load(this,id).has("product"))throw new IOException("أنشئ إعلان المنتج أولًا");pending="productImage";pick("image/*",781);break;
  case "pickImage":editable();scene(MotionProject.load(this,id),r.getString("scene"));pendingScene=r.getString("scene");pending="image";pick("image/*",781);break;
  case "pickAudio":editable();pending="audio";pick("audio/*",781);break;
  case "import":editable();pending="project";pick("application/zip",781);break;
  case "prepare":case "export":editable();if(MotionStudioService.active)throw new IOException("توجد مهمة استوديو أخرى؛ انتظر اكتمالها");if(!r.optBoolean("consent"))throw new IOException("فعّل الموافقة على المعالجة السحابية");JSONObject p=MotionProject.load(this,id);if(action.equals("export"))MotionProject.validate(p,true);if(action.equals("prepare")&&p.getString("voiceMode").equals("none"))throw new IOException("اختر تعليق قوقل أو تسجيلك للمزامنة الصوتية");pending=action.equals("prepare")?"align":"render";startActivityForResult(new Intent(this,ColabActivity.class).putExtra("authorizeSpeech",true).putExtra("autoStart",true).putExtra("motionStudio",true),782);break;
  case "cancel":if(active())startService(new Intent(this,MotionStudioService.class).setAction("cancel"));else cancel.set(true);break;
  case "share":case "saveVideo":JSONObject result=MotionProject.load(this,id).getJSONObject("result");File out=FilesUtil.resolve(this,result.getString("name"));if(action.equals("share"))share(out,"video/mp4");else{pending="saveVideo";pickSave("video/mp4",out.getName());}break;
  case "exportProject":task("تجهيز نسخة المشروع",()->{JSONObject project=MotionProject.load(this,id);File zip=FilesUtil.output(this,"zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){Set<String> names=new LinkedHashSet<>();names.add("project.json");if(project.optBoolean("ready")&&!project.getString("voiceMode").equals("none"))names.add("voice.wav");names.addAll(MotionCreative.assets(project));for(String name:names){File f=MotionProject.asset(this,id,name);if(!f.isFile())throw new IOException("ملف المشروع غير مكتمل");z.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(f)){FilesUtil.copy(in,z);}z.closeEntry();}}catch(Exception e){zip.delete();throw e;}runOnUiThread(()->share(zip,"application/zip"));});break;
  case "close":finish();break;
  default:throw new IOException("طلب غير مدعوم");
 }}
 private void pick(String mime,int code){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime),code);}
 private void pickSave(String mime,String name){startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name),783);}
 private void share(File f,String mime){Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("ملف مدار",u));startActivity(Intent.createChooser(i,"مشاركة"));}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK){pending="";return;}try{if(code==782){String mode=pending;pending="";if(!mode.equals("align")&&!mode.equals("render"))throw new IOException("أعد اختيار المعالجة");MotionStudioService.start(this,id,mode);send(new JSONObject().put("type","busy").put("message","بدء المعالجة السحابية"));return;}if(data==null||data.getData()==null)throw new IOException("لم يتم اختيار ملف");Uri uri=data.getData();if(!"content".equals(uri.getScheme()))throw new IOException("اختر الملف من منتقي الملفات");String type=pending,sid=pendingScene;pending="";if(code==783){File video=FilesUtil.resolve(this,MotionProject.load(this,id).getJSONObject("result").getString("name"));worker.execute(()->{try(InputStream in=new FileInputStream(video);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();FilesUtil.copy(in,out);send(new JSONObject().put("type","notice").put("message","حُفظ الفيديو"));}catch(Exception e){error("تعذر حفظ الفيديو");}});return;}
 task("استيراد الملف",()->{if(type.equals("project")){importProject(uri);return;}File temp=File.createTempFile("motion-import-",".data",getCacheDir());try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException();byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){if((total+=n)>((type.equals("image")||type.equals("productImage"))?8:32)*1024L*1024)throw new IOException("الملف كبير جدًا");out.write(b,0,n);}}JSONObject p=MotionProject.load(this,id);if(type.equals("productImage")){String name=MotionImages.store(this,id,temp);JSONArray ss=p.getJSONArray("scenes");for(int i=0;i<ss.length();i++){JSONObject s=ss.getJSONObject(i);if(s.optString("graphic").equals("product"))s.put("image",name).put("credit","صورة المنتج المرفقة").put("illustration",false).put("imageManual",true).put("imageAt",s.optDouble("start",0));}}else if(type.equals("image")){JSONObject s=scene(p,sid);s.put("image",MotionImages.store(this,id,temp)).put("credit","صورة مرفقة").put("illustration",false).put("imageManual",false).put("imageAt",s.optDouble("start",0));if(p.optBoolean("ready")&&!s.optString("imageAnchor").isEmpty())s.put("imageAt",JSONObject.NULL).put("needsReview",true);}else{File dest=MotionProject.asset(this,id,"recording.media");try(InputStream in=new FileInputStream(temp);OutputStream out=new FileOutputStream(dest)){FilesUtil.copy(in,out);}p.put("voiceMode","recording").put("ready",false);p.remove("audio");}p.remove("result");MotionProject.save(this,p);}finally{temp.delete();}});
 }catch(Exception e){error(e.getMessage()==null?"تعذر استيراد الملف":e.getMessage());}}
 private void importProject(Uri uri)throws Exception{String fresh=MotionProject.id();File dir=MotionProject.directory(this,fresh);boolean success=false;try(InputStream raw=getContentResolver().openInputStream(uri);ZipInputStream zip=new ZipInputStream(raw)){Set<String> seen=new HashSet<>();long total=0;ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(!seen.add(name)||seen.size()>24||!name.matches("project\\.json|voice\\.wav|asset_[a-f0-9]{32}\\.jpg")||entry.isDirectory())throw new IOException("ملف مشروع غير صالح");File target=new File(dir,name);try(OutputStream out=new FileOutputStream(target)){byte[] b=new byte[32768];int n;long size=0;while((n=zip.read(b))!=-1){if((size+=n)>32L*1024*1024||(total+=n)>128L*1024*1024)throw new IOException("المشروع كبير جدًا");out.write(b,0,n);}}zip.closeEntry();}JSONObject p=GeminiCheckpoint.read(new File(dir,"project.json"));if(p==null)throw new IOException("ملف المشروع ناقص");p.put("id",fresh);p.remove("result");MotionProject.validate(p,false);JSONArray scenes=p.getJSONArray("scenes");for(int i=0;i<scenes.length();i++){String image=scenes.getJSONObject(i).getString("image");if(!image.isEmpty()&&!new File(dir,image).isFile())throw new IOException("صور المشروع ناقصة");}for(String name:MotionCreative.assets(p))if(!new File(dir,name).isFile())throw new IOException("صور التكوين ناقصة");if(p.optBoolean("ready")&&!p.getString("voiceMode").equals("none")&&!new File(dir,"voice.wav").isFile())throw new IOException("صوت المشروع ناقص");MotionProject.save(this,p);id=fresh;success=true;}finally{if(!success){File[] files=dir.listFiles();if(files!=null)for(File f:files)f.delete();dir.delete();}}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("project",id);out.putString("pending",pending);out.putString("scene",pendingScene);}
 @Override protected void onPause(){if(web!=null)web.evaluateJavascript("document.querySelectorAll(\"audio,video\").forEach(m=>m.pause())",null);super.onPause();}
 @Override protected void onDestroy(){destroyed=true;cancel.set(true);worker.shutdownNow();if(loaded||server!=null)try{unregisterReceiver(events);}catch(Exception ignored){}if(server!=null)server.close();if(web!=null){web.removeJavascriptInterface("MotionNative");web.destroy();}super.onDestroy();}
}
